/**
 * Skill input-coverage analysis.
 *
 * The platform's current skill contract keeps the form schema and lookup
 * bindings in the instructions Markdown while tool fields/inputs are
 * structured resources. This module compares those two real sources instead
 * of inventing a second persisted schema. The headings and list shape match
 * the skill generator contract:
 *
 *   ## Input Schema
 *   - field_name (required): description
 *
 *   ## Lookup Notes
 *   - field_name: resolve_field_name (source_table)
 */
function markdownSection(markdown, title) {
    const lines = markdown.split(/\r?\n/);
    const wanted = title.trim().toLowerCase();
    const start = lines.findIndex((line) => {
        const match = /^\s*#{1,6}\s+(.+?)\s*$/.exec(line);
        return match?.[1]?.trim().toLowerCase() === wanted;
    });
    if (start < 0)
        return { found: false, lines: [] };
    const body = [];
    for (let index = start + 1; index < lines.length; index += 1) {
        const line = lines[index];
        if (/^\s*#{1,6}\s+/.test(line))
            break;
        body.push(line);
    }
    return { found: true, lines: body };
}
function unique(values) {
    return [...new Set(values)];
}
function canonicalName(value) {
    return value.toLowerCase().replace(/[^a-z0-9]/g, "");
}
export function parseSkillInputDefinition(line) {
    const match = /^\s*[-*]\s+`?([A-Za-z_][A-Za-z0-9_.-]*)`?\s*(?:\(([^)]*)\))?\s*:\s*(.*)$/.exec(line);
    if (match === null || match[1] === undefined)
        return undefined;
    const name = match[1];
    const flag = match[2]?.trim().toLowerCase();
    const required = flag === "required" ? true : undefined;
    const desc = match[3]?.trim();
    return {
        name,
        ...(required !== undefined && { required }),
        ...(desc !== undefined && desc !== "" && { description: desc }),
    };
}
export function parseSkillLookupDefinition(line) {
    const match = /^\s*[-*]\s+`?([A-Za-z_][A-Za-z0-9_.-]*)`?\s*:\s*`?([A-Za-z_][A-Za-z0-9_-]*)`?(?:\s*\(([^)]*)\))?\s*$/.exec(line);
    if (match === null || match[1] === undefined || match[2] === undefined)
        return undefined;
    const input = match[1];
    const tool = match[2];
    const source = match[3]?.trim();
    return {
        input,
        tool,
        ...(source !== undefined && source !== "" && { source }),
    };
}
function bulletKey(line) {
    return parseSkillInputDefinition(line)?.name;
}
function inputNames(section) {
    return unique(section.lines.map(bulletKey).filter((value) => value !== undefined));
}
function lookupBindings(section) {
    const out = [];
    for (const line of section.lines) {
        const parsed = parseSkillLookupDefinition(line);
        if (parsed !== undefined) {
            out.push({ input: parsed.input, tool: parsed.tool });
        }
    }
    return out;
}
export function formatSkillInputSchema(inputs) {
    if (inputs.length === 0) {
        return "## Input Schema\n\n- No input fields yet.";
    }
    const lines = ["## Input Schema", ""];
    for (const input of inputs) {
        const requiredStr = input.required === true ? " (required)" : "";
        const desc = input.description !== undefined && input.description !== "" ? `: ${input.description}` : ":";
        lines.push(`- ${input.name}${requiredStr}${desc}`);
    }
    return lines.join("\n");
}
export function formatSkillLookupNotes(lookups) {
    if (lookups.length === 0) {
        return "## Lookup Notes\n\n- No lookup tools yet.";
    }
    const lines = ["## Lookup Notes", ""];
    for (const lookup of lookups) {
        const sourceStr = lookup.source ? ` (${lookup.source})` : "";
        lines.push(`- ${lookup.input}: ${lookup.tool}${sourceStr}`);
    }
    return lines.join("\n");
}
export function deriveSkillInstructions(baseProse, inputs, lookups) {
    const raw = baseProse?.trim() ?? "";
    if (inputs === undefined && lookups === undefined) {
        return raw;
    }
    const decomposed = decomposeSkillInstructions(raw);
    const effectiveInputs = inputs !== undefined
        ? inputs
        : decomposed.inputs.length > 0
            ? decomposed.inputs
            : undefined;
    const effectiveLookups = lookups !== undefined
        ? lookups
        : decomposed.lookups.length > 0
            ? decomposed.lookups
            : undefined;
    const prose = decomposed.prose;
    const sections = [];
    if (prose !== "") {
        sections.push(prose);
    }
    if (effectiveInputs !== undefined && effectiveInputs.length > 0) {
        sections.push(formatSkillInputSchema(effectiveInputs));
    }
    else if (inputs !== undefined && inputs.length === 0) {
        sections.push(formatSkillInputSchema([]));
    }
    if (effectiveLookups !== undefined && effectiveLookups.length > 0) {
        sections.push(formatSkillLookupNotes(effectiveLookups));
    }
    else if (lookups !== undefined && lookups.length === 0) {
        sections.push(formatSkillLookupNotes([]));
    }
    return sections.join("\n\n");
}
export function decomposeSkillInstructions(markdown) {
    const lines = markdown.split(/\r?\n/);
    const inputs = [];
    const lookups = [];
    const proseLines = [];
    let currentSection = undefined;
    for (const line of lines) {
        const headerMatch = /^\s*#{1,6}\s+(.+?)\s*$/.exec(line);
        if (headerMatch !== null) {
            const title = headerMatch[1]?.trim().toLowerCase();
            if (title === "input schema") {
                currentSection = "input-schema";
                continue;
            }
            else if (title === "lookup notes") {
                currentSection = "lookup-notes";
                continue;
            }
            else {
                currentSection = undefined;
                proseLines.push(line);
                continue;
            }
        }
        if (currentSection === "input-schema") {
            const trimmed = line.trim();
            if (trimmed === "" || trimmed.toLowerCase() === "- no input fields yet.") {
                continue;
            }
            const parsed = parseSkillInputDefinition(line);
            if (parsed !== undefined) {
                inputs.push(parsed);
                continue;
            }
            currentSection = undefined;
            proseLines.push(line);
        }
        else if (currentSection === "lookup-notes") {
            const trimmed = line.trim().toLowerCase();
            if (trimmed === "" ||
                trimmed === "- no lookup tools yet." ||
                trimmed === "- no lookup tools are required.") {
                continue;
            }
            const parsed = parseSkillLookupDefinition(line);
            if (parsed !== undefined) {
                lookups.push(parsed);
                continue;
            }
            currentSection = undefined;
            proseLines.push(line);
        }
        else {
            proseLines.push(line);
        }
    }
    const prose = proseLines.join("\n").trim();
    return { prose, inputs, lookups };
}
function mentionsIdentifier(markdown, name) {
    if (name === "")
        return false;
    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return new RegExp(`(^|[^A-Za-z0-9_])${escaped}([^A-Za-z0-9_]|$)`).test(markdown);
}
function sameName(left, right) {
    return canonicalName(left) === canonicalName(right);
}
/** Compare instruction-declared form variables with the deployed tool surface. */
export function analyzeSkillInputCoverage(skill, instructions, coverageTools) {
    const schema = markdownSection(instructions, "Input Schema");
    const inputs = inputNames(schema);
    const tools = coverageTools.map((entry) => entry.name);
    if (!schema.found) {
        return {
            skill,
            inputs: [],
            tools,
            bindings: [],
            gaps: [{ kind: "input-schema-missing" }],
        };
    }
    const lookups = lookupBindings(markdownSection(instructions, "Lookup Notes"));
    const gaps = [];
    const bindings = [];
    const coveredTools = new Set();
    for (const input of inputs) {
        const targets = [];
        for (const lookup of lookups.filter((entry) => sameName(entry.input, input))) {
            if (tools.includes(lookup.tool)) {
                targets.push({ kind: "lookup", tool: lookup.tool });
                coveredTools.add(lookup.tool);
            }
            else {
                gaps.push({ kind: "missing-lookup-tool", input, tool: lookup.tool });
            }
        }
        for (const coverageTool of coverageTools) {
            for (const field of coverageTool.fields.filter((entry) => sameName(entry, input))) {
                targets.push({ kind: "field", tool: coverageTool.name, name: field });
                coveredTools.add(coverageTool.name);
            }
            for (const parameter of coverageTool.inputs.filter((entry) => sameName(entry, input))) {
                targets.push({ kind: "input", tool: coverageTool.name, name: parameter });
                coveredTools.add(coverageTool.name);
            }
        }
        if (targets.length === 0)
            gaps.push({ kind: "missing-field", input });
        bindings.push({ input, targets });
    }
    for (const lookup of lookups) {
        if (!inputs.some((input) => sameName(input, lookup.input))) {
            gaps.push({ kind: "unbound-lookup", input: lookup.input, tool: lookup.tool });
        }
    }
    for (const coverageTool of coverageTools) {
        if (coveredTools.has(coverageTool.name) || mentionsIdentifier(instructions, coverageTool.name))
            continue;
        gaps.push({ kind: "leftover-tool", tool: coverageTool.name });
    }
    return { skill, inputs, tools, bindings, gaps };
}
function describeTarget(target) {
    if (target.kind === "lookup")
        return `lookup tool ${JSON.stringify(target.tool)}`;
    return `tool ${JSON.stringify(target.tool)} ${target.kind} ${JSON.stringify(target.name)}`;
}
/** Informational coverage lines emitted on stderr and in JSON `reports`. */
export function skillCoverageReportLines(report) {
    const lines = [
        `skill ${JSON.stringify(report.skill)} input coverage report: ${report.inputs.length} form variables, ${report.tools.length} tools, ${report.gaps.length} gaps`,
    ];
    for (const binding of report.bindings) {
        lines.push(`skill ${JSON.stringify(report.skill)} input coverage: ${JSON.stringify(binding.input)} -> ${binding.targets.length > 0 ? binding.targets.map(describeTarget).join(", ") : "UNBOUND"}`);
    }
    return lines;
}
/** Only actionable gaps; these remain warnings and JSON `diagnostics`. */
export function skillCoverageGapDiagnostics(report) {
    const lines = [];
    for (const gap of report.gaps) {
        if (gap.kind === "input-schema-missing") {
            lines.push(`skill ${JSON.stringify(report.skill)} input coverage gap [input-schema-missing]: instructions have no "## Input Schema" section; tool coverage cannot be verified`);
        }
        else if (gap.kind === "missing-field") {
            lines.push(`skill ${JSON.stringify(report.skill)} input coverage gap [missing-field]: form variable ${JSON.stringify(gap.input)} has no skill field or tool input binding`);
        }
        else if (gap.kind === "missing-lookup-tool") {
            lines.push(`skill ${JSON.stringify(report.skill)} input coverage gap [missing-lookup-tool]: ${JSON.stringify(gap.input)} names lookup tool ${JSON.stringify(gap.tool)}, but that tool is absent`);
        }
        else if (gap.kind === "unbound-lookup") {
            lines.push(`skill ${JSON.stringify(report.skill)} input coverage gap [unbound-lookup]: lookup ${JSON.stringify(gap.input)} -> ${JSON.stringify(gap.tool)} has no matching Input Schema field`);
        }
        else {
            lines.push(`skill ${JSON.stringify(report.skill)} input coverage gap [leftover-tool]: tool ${JSON.stringify(gap.tool)} is neither bound to an Input Schema field nor referenced by the instructions`);
        }
    }
    return lines;
}
function stringsAt(value, key) {
    if (typeof value !== "object" || value === null)
        return [];
    const entries = value[key];
    if (!Array.isArray(entries))
        return [];
    const nameKey = key === "fields" ? "name" : "parameterName";
    return entries.flatMap((entry) => {
        if (typeof entry !== "object" || entry === null || Array.isArray(entry))
            return [];
        const name = entry[nameKey];
        return typeof name === "string" && name !== "" ? [name] : [];
    });
}
/** Convert a skill def() payload's closed tool envelopes to analyzer input. */
export function coverageToolsFromWire(entries) {
    return entries.flatMap((entry) => {
        const typeKey = Object.keys(entry)[0];
        const inner = typeKey === undefined ? undefined : entry[typeKey];
        if (typeof inner !== "object" || inner === null || Array.isArray(inner))
            return [];
        const name = inner["name"];
        if (typeof name !== "string" || name === "")
            return [];
        return [{ name, fields: stringsAt(inner, "fields"), inputs: stringsAt(inner, "inputs") }];
    });
}
